changeSet.sql:
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence;
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence
    CHECK (presence IN ('PRESENT', 'ABSENT', 'NOT_APPLICABLE', 'INDETERMINATE'));
-- The coupling, restated over four values instead of three: assessment is present exactly when the
-- presence carries a direction. INDETERMINATE joins NOT_APPLICABLE on the null side, and that is the
-- whole point of the value -- a run that could not settle the question must not be able to smuggle a
-- GOOD or a BAD out with it.
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence_assessment;
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence_assessment
    CHECK ((presence IN ('NOT_APPLICABLE', 'INDETERMINATE') AND assessment IS NULL)
        OR (presence IN ('PRESENT', 'ABSENT') AND assessment IS NOT NULL));

changeSet.rollback:
-- Rolling back the vocabulary means the rows written under it are no longer representable; drop
-- them rather than relabel, because every candidate relabel is a lie: NOT_APPLICABLE would assert
-- the practice did not apply, and PRESENT/ABSENT would invent the verdict the run declined to give.
DELETE FROM observation WHERE presence = 'INDETERMINATE';
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence_assessment;
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence_assessment
    CHECK ((presence = 'NOT_APPLICABLE' AND assessment IS NULL)
        OR (presence IN ('PRESENT', 'ABSENT') AND assessment IS NOT NULL));
ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_presence;
ALTER TABLE observation ADD CONSTRAINT chk_observation_presence
    CHECK (presence IN ('PRESENT', 'ABSENT', 'NOT_APPLICABLE'));

changeSet.sql:
-- Both plpgsql bodies name the column as text, so a rename leaves them referring to a column -- that no longer exists; they are recreated below. The trigger's own UPDATE OF list and the -- CHECK expressions are catalog references and follow the rename by themselves, but the two -- CHECKs are dropped and re-added anyway so the constraint reads in the new vocabulary -- rather than being a renamed relic nobody can grep for. ALTER TABLE practice_revision DROP CONSTRAINT IF EXISTS ck_practice_revision_definition_shape, DROP CONSTRAINT IF EXISTS ck_practice_revision_trigger_events; ALTER TABLE curated_practice_override DROP CONSTRAINT IF EXISTS ck_curated_practice_override_shape, DROP CONSTRAINT IF EXISTS ck_curated_practice_override_trigger_events;
ALTER TABLE practice RENAME COLUMN trigger_events TO bindings; ALTER TABLE practice_revision RENAME COLUMN trigger_events TO bindings; ALTER TABLE curated_practice_override RENAME COLUMN trigger_events TO bindings;
ALTER TABLE practice_revision ADD CONSTRAINT ck_practice_revision_definition_shape CHECK ( ( slug IS NULL AND name IS NULL AND applies_to IS NULL AND bindings IS NULL AND review_rule_fingerprint IS NULL ) OR ( slug IS NOT NULL AND name IS NOT NULL AND applies_to IS NOT NULL AND bindings IS NOT NULL ) ), ADD CONSTRAINT ck_practice_revision_bindings CHECK (bindings IS NULL OR jsonb_typeof(bindings) = 'array'); ALTER TABLE curated_practice_override ADD CONSTRAINT ck_curated_practice_override_shape CHECK ( (name IS NULL AND applies_to IS NULL AND bindings IS NULL AND criteria IS NULL AND precompute_script IS NULL AND why_it_matters IS NULL AND what_good_looks_like IS NULL AND area_slug IS NULL AND based_on_digest IS NULL) OR (name IS NOT NULL AND applies_to IS NOT NULL AND bindings IS NOT NULL AND criteria IS NOT NULL) ), ADD CONSTRAINT ck_curated_practice_override_bindings CHECK (bindings IS NULL OR jsonb_typeof(bindings) = 'array');
CREATE OR REPLACE FUNCTION enforce_practice_revision_immutability() RETURNS trigger LANGUAGE plpgsql AS $immutable_revision$ BEGIN IF NEW.practice_id = OLD.practice_id AND NEW.revision_number = OLD.revision_number AND NEW.created_at = OLD.created_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug AND NEW.name IS NOT DISTINCT FROM OLD.name AND NEW.applies_to IS NOT DISTINCT FROM OLD.applies_to AND NEW.bindings IS NOT DISTINCT FROM OLD.bindings AND NEW.criteria = OLD.criteria AND NEW.precompute_script IS NOT DISTINCT FROM OLD.precompute_script AND NEW.automated_review_policy IS NOT DISTINCT FROM OLD.automated_review_policy AND NEW.why_it_matters IS NOT DISTINCT FROM OLD.why_it_matters AND NEW.what_good_looks_like IS NOT DISTINCT FROM OLD.what_good_looks_like AND NEW.area_slug IS NOT DISTINCT FROM OLD.area_slug AND NEW.area_name IS NOT DISTINCT FROM OLD.area_name AND NEW.area_description IS NOT DISTINCT FROM OLD.area_description AND NEW.area_icon IS NOT DISTINCT FROM OLD.area_icon AND NEW.area_color IS NOT DISTINCT FROM OLD.area_color AND ( NEW.review_rule_fingerprint IS NOT DISTINCT FROM OLD.review_rule_fingerprint OR OLD.review_rule_fingerprint IS NULL ) THEN RETURN NEW; END IF; RAISE EXCEPTION 'practice revisions are immutable' USING ERRCODE = '55000'; END; $immutable_revision$;
CREATE OR REPLACE FUNCTION enforce_practice_current_revision_projection() RETURNS trigger LANGUAGE plpgsql AS $current_projection$ BEGIN IF NOT EXISTS ( SELECT 1 FROM practice practice JOIN practice_revision revision ON revision.id = practice.current_revision_id AND revision.practice_id = practice.id LEFT JOIN practice_area area ON area.id = practice.practice_area_id WHERE practice.id = NEW.id AND revision.slug = practice.slug AND revision.name = practice.name AND revision.applies_to = practice.applies_to AND revision.bindings = practice.bindings AND revision.criteria = practice.criteria AND revision.precompute_script IS NOT DISTINCT FROM practice.precompute_script AND revision.automated_review_policy = practice.automated_review_policy AND revision.why_it_matters IS NOT DISTINCT FROM practice.why_it_matters AND revision.what_good_looks_like IS NOT DISTINCT FROM practice.what_good_looks_like AND revision.area_slug IS NOT DISTINCT FROM area.slug ) THEN RAISE EXCEPTION 'practice current revision does not match its current projection' USING ERRCODE = '23514'; END IF; RETURN NULL; END; $current_projection$;
-- One binding carrying every signal the practice used to be triggered by, reading exactly -- what its named policy used to require. Nothing a practice reviewed changes here; only -- where it is written down. A stored trigger-event literal outside the nine the authoring -- vocabulary allowed is dropped, and a row left with none falls back to the artifact kind's -- opening signal so it stays loadable and still says what it is about. CREATE OR REPLACE FUNCTION migrate_practice_bindings(kind text, events jsonb, policy jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $migrate_bindings$ SELECT jsonb_build_array(jsonb_build_object( 'signals', COALESCE(( SELECT jsonb_agg(signal ORDER BY signal) FROM ( SELECT CASE event WHEN 'PullRequestCreated' THEN 'scm.pull_request.opened' WHEN 'PullRequestReady' THEN 'scm.pull_request.ready' WHEN 'PullRequestSynchronized' THEN 'scm.pull_request.synchronized' WHEN 'ReviewSubmitted' THEN 'scm.pull_request.reviewed' WHEN 'PullRequestMerged' THEN 'scm.pull_request.merged' WHEN 'PullRequestClosed' THEN 'scm.pull_request.closed' WHEN 'IssueCreated' THEN 'scm.issue.opened' WHEN 'IssueLabeled' THEN 'scm.issue.labeled' WHEN 'IssueClosed' THEN 'scm.issue.closed' END AS signal FROM jsonb_array_elements_text(COALESCE(events, '[]'::jsonb)) AS event ) AS mapped WHERE signal IS NOT NULL ), jsonb_build_array(CASE kind WHEN 'chat.conversation_thread' THEN 'chat.conversation_thread.settled' WHEN 'scm.issue' THEN 'scm.issue.opened' ELSE 'scm.pull_request.opened' END)), 'needs', COALESCE(policy->'needs', '[]'::jsonb), 'onDrafts', false )) $migrate_bindings$;
UPDATE practice SET bindings = migrate_practice_bindings(applies_to, bindings, automated_review_policy), automated_review_policy = automated_review_policy - 'needs' WHERE jsonb_typeof(bindings) = 'array' AND NOT jsonb_path_exists(bindings, '$[*].signals'); UPDATE curated_practice_override SET bindings = migrate_practice_bindings(applies_to, bindings, automated_review_policy), automated_review_policy = automated_review_policy - 'needs' WHERE bindings IS NOT NULL AND jsonb_typeof(bindings) = 'array' AND NOT jsonb_path_exists(bindings, '$[*].signals'); ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update; UPDATE practice_revision SET bindings = migrate_practice_bindings(applies_to, bindings, automated_review_policy), automated_review_policy = automated_review_policy - 'needs' WHERE bindings IS NOT NULL AND jsonb_typeof(bindings) = 'array' AND NOT jsonb_path_exists(bindings, '$[*].signals'); -- Same reason as -21 and -22: the bindings and the policy both feed the review-rule -- fingerprint, so every stored one now describes a rule set written in a shape that no -- longer exists. CatalogProvenanceBackfill recomputes them on the next boot. UPDATE practice_revision SET review_rule_fingerprint = NULL WHERE slug IS NOT NULL AND automated_review_policy IS NOT NULL; ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update; DROP FUNCTION migrate_practice_bindings(text, jsonb, jsonb);

rollback.sql:
-- The signals map back to their literals and the needs go back onto the policy as the -- union across bindings, which is what one shared policy could express. Per-binding -- evidence and the draft flag have no pre-binding spelling and are dropped; that is the -- capability this changeset adds, so losing it on the way back is the whole point. CREATE OR REPLACE FUNCTION restore_practice_trigger_events(bindings jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $restore_events$ SELECT COALESCE(( SELECT jsonb_agg(DISTINCT event) FROM ( SELECT CASE signal WHEN 'scm.pull_request.opened' THEN 'PullRequestCreated' WHEN 'scm.pull_request.ready' THEN 'PullRequestReady' WHEN 'scm.pull_request.synchronized' THEN 'PullRequestSynchronized' WHEN 'scm.pull_request.reviewed' THEN 'ReviewSubmitted' WHEN 'scm.pull_request.merged' THEN 'PullRequestMerged' WHEN 'scm.pull_request.closed' THEN 'PullRequestClosed' WHEN 'scm.issue.opened' THEN 'IssueCreated' WHEN 'scm.issue.labeled' THEN 'IssueLabeled' WHEN 'scm.issue.closed' THEN 'IssueClosed' END AS event FROM jsonb_array_elements(COALESCE(bindings, '[]'::jsonb)) AS binding, jsonb_array_elements_text(binding->'signals') AS signal ) AS mapped WHERE event IS NOT NULL ), '[]'::jsonb) $restore_events$;
CREATE OR REPLACE FUNCTION restore_policy_needs(policy jsonb, bindings jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $restore_needs$ SELECT policy || jsonb_build_object('needs', COALESCE(( SELECT jsonb_agg(DISTINCT need ORDER BY need) FROM jsonb_array_elements(COALESCE(bindings, '[]'::jsonb)) AS binding, jsonb_array_elements(binding->'needs') AS need ), '[]'::jsonb)) $restore_needs$;
UPDATE practice SET automated_review_policy = restore_policy_needs(automated_review_policy, bindings), bindings = restore_practice_trigger_events(bindings) WHERE jsonb_path_exists(bindings, '$[*].signals'); UPDATE curated_practice_override SET automated_review_policy = restore_policy_needs(automated_review_policy, bindings), bindings = restore_practice_trigger_events(bindings) WHERE bindings IS NOT NULL AND jsonb_path_exists(bindings, '$[*].signals'); ALTER TABLE practice_revision DISABLE TRIGGER practice_revision_immutable_update; UPDATE practice_revision SET automated_review_policy = restore_policy_needs(automated_review_policy, bindings), bindings = restore_practice_trigger_events(bindings) WHERE bindings IS NOT NULL AND jsonb_path_exists(bindings, '$[*].signals'); UPDATE practice_revision SET review_rule_fingerprint = NULL WHERE slug IS NOT NULL AND automated_review_policy IS NOT NULL; ALTER TABLE practice_revision ENABLE TRIGGER practice_revision_immutable_update; DROP FUNCTION restore_practice_trigger_events(jsonb); DROP FUNCTION restore_policy_needs(jsonb, jsonb);
ALTER TABLE practice_revision DROP CONSTRAINT IF EXISTS ck_practice_revision_definition_shape, DROP CONSTRAINT IF EXISTS ck_practice_revision_bindings; ALTER TABLE curated_practice_override DROP CONSTRAINT IF EXISTS ck_curated_practice_override_shape, DROP CONSTRAINT IF EXISTS ck_curated_practice_override_bindings;
ALTER TABLE practice RENAME COLUMN bindings TO trigger_events; ALTER TABLE practice_revision RENAME COLUMN bindings TO trigger_events; ALTER TABLE curated_practice_override RENAME COLUMN bindings TO trigger_events;
ALTER TABLE practice_revision ADD CONSTRAINT ck_practice_revision_definition_shape CHECK ( ( slug IS NULL AND name IS NULL AND applies_to IS NULL AND trigger_events IS NULL AND review_rule_fingerprint IS NULL ) OR ( slug IS NOT NULL AND name IS NOT NULL AND applies_to IS NOT NULL AND trigger_events IS NOT NULL ) ), ADD CONSTRAINT ck_practice_revision_trigger_events CHECK (trigger_events IS NULL OR jsonb_typeof(trigger_events) = 'array'); ALTER TABLE curated_practice_override ADD CONSTRAINT ck_curated_practice_override_shape CHECK ( (name IS NULL AND applies_to IS NULL AND trigger_events IS NULL AND criteria IS NULL AND precompute_script IS NULL AND why_it_matters IS NULL AND what_good_looks_like IS NULL AND area_slug IS NULL AND based_on_digest IS NULL) OR (name IS NOT NULL AND applies_to IS NOT NULL AND trigger_events IS NOT NULL AND criteria IS NOT NULL) ), ADD CONSTRAINT ck_curated_practice_override_trigger_events CHECK (trigger_events IS NULL OR jsonb_typeof(trigger_events) = 'array');
CREATE OR REPLACE FUNCTION enforce_practice_revision_immutability() RETURNS trigger LANGUAGE plpgsql AS $immutable_revision$ BEGIN IF NEW.practice_id = OLD.practice_id AND NEW.revision_number = OLD.revision_number AND NEW.created_at = OLD.created_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug AND NEW.name IS NOT DISTINCT FROM OLD.name AND NEW.applies_to IS NOT DISTINCT FROM OLD.applies_to AND NEW.trigger_events IS NOT DISTINCT FROM OLD.trigger_events AND NEW.criteria = OLD.criteria AND NEW.precompute_script IS NOT DISTINCT FROM OLD.precompute_script AND NEW.automated_review_policy IS NOT DISTINCT FROM OLD.automated_review_policy AND NEW.why_it_matters IS NOT DISTINCT FROM OLD.why_it_matters AND NEW.what_good_looks_like IS NOT DISTINCT FROM OLD.what_good_looks_like AND NEW.area_slug IS NOT DISTINCT FROM OLD.area_slug AND NEW.area_name IS NOT DISTINCT FROM OLD.area_name AND NEW.area_description IS NOT DISTINCT FROM OLD.area_description AND NEW.area_icon IS NOT DISTINCT FROM OLD.area_icon AND NEW.area_color IS NOT DISTINCT FROM OLD.area_color AND ( NEW.review_rule_fingerprint IS NOT DISTINCT FROM OLD.review_rule_fingerprint OR OLD.review_rule_fingerprint IS NULL ) THEN RETURN NEW; END IF; RAISE EXCEPTION 'practice revisions are immutable' USING ERRCODE = '55000'; END; $immutable_revision$; CREATE OR REPLACE FUNCTION enforce_practice_current_revision_projection() RETURNS trigger LANGUAGE plpgsql AS $current_projection$ BEGIN IF NOT EXISTS ( SELECT 1 FROM practice practice JOIN practice_revision revision ON revision.id = practice.current_revision_id AND revision.practice_id = practice.id LEFT JOIN practice_area area ON area.id = practice.practice_area_id WHERE practice.id = NEW.id AND revision.slug = practice.slug AND revision.name = practice.name AND revision.applies_to = practice.applies_to AND revision.trigger_events = practice.trigger_events AND revision.criteria = practice.criteria AND revision.precompute_script IS NOT DISTINCT FROM practice.precompute_script AND revision.automated_review_policy = practice.automated_review_policy AND revision.why_it_matters IS NOT DISTINCT FROM practice.why_it_matters AND revision.what_good_looks_like IS NOT DISTINCT FROM practice.what_good_looks_like AND revision.area_slug IS NOT DISTINCT FROM area.slug ) THEN RAISE EXCEPTION 'practice current revision does not match its current projection' USING ERRCODE = '23514'; END IF; RETURN NULL; END; $current_projection$;

changeSet.sql:
-- add-backfill-drop, exactly as this file already did for is_active -> used_in_new_reviews and
-- trigger_events -> bindings. The boolean it replaces was introduced by THIS changelog and has
-- never been released, so there is no deployed schema in which the old name has to survive.
ALTER TABLE practice ADD COLUMN review_tier VARCHAR(16);
-- Both existing states map exactly and without judgement: a practice that was used in new reviews
-- was reviewed AND delivered everywhere, which is ENGAGE; one that was not was not reviewed at
-- all, which is OFF. MEASURE and COACH are new expressive room, never a re-reading of old data.
UPDATE practice SET review_tier = CASE WHEN used_in_new_reviews THEN 'ENGAGE' ELSE 'OFF' END;
ALTER TABLE practice ALTER COLUMN review_tier SET NOT NULL;
ALTER TABLE practice ALTER COLUMN review_tier SET DEFAULT 'ENGAGE';
ALTER TABLE practice ADD CONSTRAINT chk_practice_review_tier
    CHECK (review_tier IN ('OFF', 'MEASURE', 'COACH', 'ENGAGE'));
-- The gate reads (workspace_id, tier); the index it replaces covered the boolean this widens.
DROP INDEX IF EXISTS idx_practice_workspace_usage;
CREATE INDEX IF NOT EXISTS idx_practice_workspace_tier ON practice (workspace_id, review_tier);
ALTER TABLE practice DROP COLUMN used_in_new_reviews;

changeSet.rollback:
ALTER TABLE practice ADD COLUMN used_in_new_reviews BOOLEAN;
-- The inverse of the forward map is lossy in one direction only: MEASURE and COACH are states the
-- boolean cannot express. They collapse to TRUE rather than FALSE because both of them DO review
-- the practice, and the boolean's only true meaning was "review this"; sending them to FALSE would
-- silently stop a measurement the workspace asked for.
UPDATE practice SET used_in_new_reviews = (review_tier <> 'OFF');
ALTER TABLE practice ALTER COLUMN used_in_new_reviews SET NOT NULL;
ALTER TABLE practice ALTER COLUMN used_in_new_reviews SET DEFAULT TRUE;
DROP INDEX IF EXISTS idx_practice_workspace_tier;
CREATE INDEX IF NOT EXISTS idx_practice_workspace_usage ON practice (workspace_id, used_in_new_reviews);
ALTER TABLE practice DROP CONSTRAINT IF EXISTS chk_practice_review_tier;
ALTER TABLE practice DROP COLUMN review_tier;

-- Rolling the vocabulary back makes these rows unrepresentable. Deleting them is the honest
-- move: every remaining reason would assert something the run did not decide, and the
-- observation each row points at is untouched, so nothing measured is lost with them.
DELETE FROM feedback WHERE suppression_reason = 'PRACTICE_TIER_QUIET';
ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_suppression_reason;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED'));

-- Narrowing the vocabulary makes these rows unrepresentable. Deleting them is the honest
-- move and is safe: a signal row is a record that an occurrence was seen and settled, so
-- removing it returns the occurrence to "never seen" -- which, without the campaign that
-- recorded it, is the truth. The reviews it triggered keep their own rows.
DELETE FROM artifact_signal WHERE discovered_via = 'BACKFILL';
ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS ck_artifact_signal_discovered_via;
ALTER TABLE artifact_signal ADD CONSTRAINT ck_artifact_signal_discovered_via
    CHECK (discovered_via IN ('EVENT','SYNC','MANUAL'));

DELETE FROM feedback WHERE suppression_reason = 'BACKFILL_QUIET';
ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_suppression_reason;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED',
        'PRACTICE_TIER_QUIET'));

rollback.sql:
DO $rollback$
BEGIN
    -- The trail is append-only by trigger, so a row written under this value can only be
    -- left where it is; narrowing the constraint under it would make the table unreadable
    -- to its own guard. Warn and keep the wider vocabulary.
    IF EXISTS (SELECT 1 FROM config_audit_event WHERE entity_type = 'REVIEW_BACKFILL_RUN') THEN
        RAISE WARNING 'The audit entity-type constraint remains widened because append-only history contains REVIEW_BACKFILL_RUN rows';
        RETURN;
    END IF;

    ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
    ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
        CHECK (entity_type IN (
            'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
            'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
            'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE', 'PRACTICE_USAGE',
            'PRACTICE_DEFINITION', 'PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA',
            'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
            'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
            'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
        ));
END
$rollback$;

changeSet.sql:
CREATE TABLE review_backfill_run ( id UUID PRIMARY KEY, workspace_id BIGINT NOT NULL, artifact_kind VARCHAR(64) NOT NULL, from_at TIMESTAMPTZ NOT NULL, to_at TIMESTAMPTZ NOT NULL, status VARCHAR(24) NOT NULL, pause_reason VARCHAR(32), estimated_artifacts INTEGER NOT NULL, -- Nullable, and null means "we could not price this". Never defaulted to zero: a zero on -- the confirmation screen reads as "free", which is the one thing this number must never -- say when it does not know. estimated_cost_usd NUMERIC(12,4), cursor_artifact_id BIGINT, submitted_count INTEGER NOT NULL DEFAULT 0, passed_count INTEGER NOT NULL DEFAULT 0, requested_by_account_id BIGINT NOT NULL, confirmed_by_account_id BIGINT, created_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL, CONSTRAINT fk_review_backfill_run_workspace FOREIGN KEY (workspace_id) REFERENCES workspace (id) ON DELETE CASCADE, CONSTRAINT ck_review_backfill_run_status CHECK (status IN ('AWAITING_CONFIRMATION','RUNNING','PAUSED','COMPLETED','CANCELLED')), CONSTRAINT ck_review_backfill_run_pause_reason CHECK (pause_reason IS NULL OR pause_reason IN ('BUDGET_EXHAUSTED','BINDING_DISABLED','WORKSPACE_UNAVAILABLE')), -- A pause reason is meaningful only while paused, and a paused run without one is a run -- nobody can be told how to resume. CONSTRAINT ck_review_backfill_run_pause_coherent CHECK ((status = 'PAUSED') = (pause_reason IS NOT NULL)), CONSTRAINT ck_review_backfill_run_window CHECK (from_at < to_at), CONSTRAINT ck_review_backfill_run_counts CHECK (estimated_artifacts >= 0 AND submitted_count >= 0 AND passed_count >= 0), -- Never authorised without a name against it. CONSTRAINT ck_review_backfill_run_confirmed CHECK (status = 'AWAITING_CONFIRMATION' OR status = 'CANCELLED' OR confirmed_by_account_id IS NOT NULL) );
CREATE INDEX idx_review_backfill_run_workspace ON review_backfill_run (workspace_id, created_at); CREATE INDEX idx_review_backfill_run_status ON review_backfill_run (status);
-- One campaign under way per workspace, enforced here and not only in the service: two -- overlapping campaigns each read the other's ledger rows as "already covered", so neither -- covers the scope its estimate described and the confirmation the admin gave describes -- neither run. CREATE UNIQUE INDEX uq_review_backfill_run_active ON review_backfill_run (workspace_id) WHERE status IN ('RUNNING', 'PAUSED');

ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_artifact_kind;
ALTER TABLE observation ADD CONSTRAINT chk_observation_artifact_kind
    CHECK (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64);

ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_artifact_kind;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_artifact_kind
    CHECK (artifact_kind IS NULL
           OR (artifact_kind ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(artifact_kind) <= 64));

ALTER TABLE practice_revision DROP CONSTRAINT IF EXISTS ck_practice_revision_applies_to;
ALTER TABLE practice_revision ADD CONSTRAINT ck_practice_revision_applies_to
    CHECK (applies_to IS NULL
           OR (applies_to ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(applies_to) <= 64));

ALTER TABLE curated_practice_override DROP CONSTRAINT IF EXISTS ck_curated_practice_override_applies_to;
ALTER TABLE curated_practice_override ADD CONSTRAINT ck_curated_practice_override_applies_to
    CHECK (applies_to IS NULL
           OR (applies_to ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$' AND length(applies_to) <= 64));

rollback.sql:
DO $$
DECLARE offending text;
BEGIN
    SELECT string_agg(DISTINCT entry, ', ') INTO offending FROM (
        SELECT 'observation.artifact_kind=' || artifact_kind AS entry FROM observation
         WHERE artifact_kind NOT IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread')
        UNION ALL
        SELECT 'feedback.artifact_kind=' || artifact_kind FROM feedback
         WHERE artifact_kind IS NOT NULL
           AND artifact_kind NOT IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread')
        UNION ALL
        SELECT 'practice_revision.applies_to=' || applies_to FROM practice_revision
         WHERE applies_to IS NOT NULL
           AND applies_to NOT IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread')
        UNION ALL
        SELECT 'curated_practice_override.applies_to=' || applies_to FROM curated_practice_override
         WHERE applies_to IS NOT NULL
           AND applies_to NOT IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread')
    ) found;
    IF offending IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot restore the three-kind allowlist: rows exist for kinds outside it (%). Remove or migrate those practices and their observations first — this rollback will not delete them for you.', offending;
    END IF;
END $$;

ALTER TABLE observation DROP CONSTRAINT IF EXISTS chk_observation_artifact_kind;
ALTER TABLE observation ADD CONSTRAINT chk_observation_artifact_kind
    CHECK (artifact_kind IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread'));

ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_artifact_kind;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_artifact_kind
    CHECK (artifact_kind IS NULL
           OR artifact_kind IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread'));

ALTER TABLE practice_revision DROP CONSTRAINT IF EXISTS ck_practice_revision_applies_to;
ALTER TABLE practice_revision ADD CONSTRAINT ck_practice_revision_applies_to
    CHECK (applies_to IS NULL
           OR applies_to IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread'));

ALTER TABLE curated_practice_override DROP CONSTRAINT IF EXISTS ck_curated_practice_override_applies_to;
ALTER TABLE curated_practice_override ADD CONSTRAINT ck_curated_practice_override_applies_to
    CHECK (applies_to IS NULL
           OR applies_to IN ('scm.pull_request', 'scm.issue', 'chat.conversation_thread'));

changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_artifact_signal_requested_by
    ON artifact_signal (requested_by_user_id, occurred_at)
    WHERE requested_by_user_id IS NOT NULL;

changeSet.rollback:
DROP INDEX IF EXISTS idx_artifact_signal_requested_by;
ALTER TABLE artifact_signal DROP CONSTRAINT IF EXISTS sfk_artifact_signal_requested_by;
ALTER TABLE artifact_signal DROP COLUMN IF EXISTS requested_by_user_id;
